cat > s3.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/pricing');
await p.waitForTimeout(1000);
await p.hover('tr[data-sku="P-1048"]');
await p.click('tr[data-sku="P-1048"] .setd');
const r = await p.$eval('#track', t => { const b=t.getBoundingClientRect(); return {x:b.left,y:b.top+b.height/2}; });
await p.mouse.move(r.x+264, r.y);
await p.mouse.down(); await p.mouse.up();
console.log('val', await p.textContent('#val'), 'psku', await p.textContent('#psku'));
if ((await p.textContent('#val')) === '33%') {
  await p.click('#apply');
  await p.waitForTimeout(800);
}
console.log(await p.$$eval('#pt tbody tr', rs => rs.map(r => r.dataset.sku + ' ' + r.querySelector('.d').textContent).join('\n')));
await b.close();
EOF
